class DbConfTest(unittest.TestCase):
    def make(self, url):
        d = tmpdir()
        self.addCleanup(shutil.rmtree, d, True)
        path = os.path.join(d, "c.ini")
        write(path, "[db]\nurl = %s\npool = 5\n" % url)
