            for v in RANDOM:
                self.assertEqual(rules('%s = "%s"' % (name, v)), [(1, "high-entropy")], (name, v))
        self.assertEqual(rules("x: 1\n{'session_key': '%s'}\n" % RANDOM[0]), [(2, "high-entropy")])

